<h2>Immutable work history</h2><ol class="damage-history"><?php foreach ($events as $event): $snapshot = json_decode($event['after_json'], true, 512, JSON_THROW_ON_ERROR); ?><li><strong><?= esc(ucwords(str_replace('_', ' ', $event['event_code']))) ?></strong> · Version <?= (int) $event['job_version'] ?> · <?= esc((string) $event['recorded_at']) ?> · Operator <?= (int) $event['actor_user_id'] ?><p>Occurrence: <?= esc((string) ($event['occurred_at'] ?? 'Exact time unknown / not applicable')) ?></p><?php if ($event['reason'] !== null): ?><p><?= nl2br(esc($event['reason'])) ?></p><?php endif; ?><details><summary>Recorded work state and outcomes</summary><p><?= esc($snapshot['job']['summary']) ?> · <?= esc(\Config\VehicleDamage::WORK_STATUSES[$snapshot['job']['status_code']]) ?></p><p>Started: <?= esc((string) ($snapshot['job']['started_at'] ?? 'Not recorded')) ?> · Completed: <?= esc((string) ($snapshot['job']['completed_at'] ?? 'Not recorded')) ?></p><?php if ($snapshot['job']['completion_note'] !== null): ?><p><?= nl2br(esc($snapshot['job']['completion_note'])) ?></p><?php endif; ?><ul><?php foreach ($snapshot['members'] as $entry): ?><li>Condition <?= (int) $entry['vehicle_damage_item_id'] ?> · <?= esc(\Config\VehicleDamage::WORK_RESULTS[$entry['result_code']]) ?><?= $entry['withdrawn_at'] === null ? '' : ' · Withdrawn' ?><?php if ($entry['note'] !== null): ?><p><?= nl2br(esc($entry['note'])) ?></p><?php endif; ?></li><?php endforeach; ?></ul></details></li><?php endforeach; ?></ol>
